	@Test
	void exactEmptyProofTracksSnapshotAndNewDataRevision(@TempDir Path root) throws Exception {
		try (Fixture fixture = fixture(root);
				SailRepositoryConnection oldSnapshot = fixture.repository.getConnection();
				SailRepositoryConnection live = fixture.repository.getConnection()) {
			String query = countQuery("FILTER(?code = \"inserted-after-plan\")");
			IRI linkedMedication = iri("medication-patient-medication");
			IRI codePredicate = iri("code");
			Literal insertedCode = SimpleValueFactory.getInstance().createLiteral("inserted-after-plan");
			oldSnapshot.begin(IsolationLevels.SNAPSHOT);
			SailTupleQuery oldPrepared = prepared(oldSnapshot, query, false);
			SailTupleQuery livePrepared = prepared(live, query, false);
			assertThat(oldSnapshot.hasStatement(linkedMedication, codePredicate, insertedCode, false))
					.as("a normal statement read in the pinned transaction sees the old data revision")
					.isFalse();
			assertThat(count(oldPrepared)).isEqualTo(5L);
			assertThat(count(livePrepared)).isEqualTo(5L);

			try (SailRepositoryConnection writer = fixture.repository.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				writer.add(linkedMedication, codePredicate, insertedCode);
				writer.commit();
			}
			assertThat(fixture.store.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS))
					.as(fixture.store.getDirectAdjacencyReadinessDescription())
					.isTrue();

			assertThat(oldSnapshot.hasStatement(linkedMedication, codePredicate, insertedCode, false))
					.as("SNAPSHOT isolation keeps ordinary statement reads on the retained transaction source")
					.isFalse();
			assertThat(count(oldPrepared))
					.as("an older read snapshot retains the data version that proved the finite domain empty")
					.isEqualTo(5L);
			assertThat(count(livePrepared))
					.as("the same prepared query must recheck its proof after the store revision changes")
					.isEqualTo(4L);
			oldSnapshot.rollback();
		}
	}

	@Test
	void repeatedEvaluationRecapturesAMutablePreparedLiteral(@TempDir Path root) throws Exception {
		try (Fixture fixture = fixture(root);
				SailRepositoryConnection connection = fixture.repository.getConnection()) {
			SailTupleQuery prepared = prepared(connection,
					countQuery("FILTER(?code = \"finite-value-not-present\")"), false);
			LmdbLiteral finiteLiteral = (LmdbLiteral) fixture.store.getValueFactory()
					.createLiteral("finite-value-not-present");
			int[] replaced = { 0 };
			prepared.getParsedQuery()
					.getTupleExpr()
					.visit(new AbstractQueryModelVisitor<RuntimeException>() {
						@Override
						public void meet(ValueConstant node) {
							if (node.getValue() instanceof Literal literal
									&& "finite-value-not-present".equals(literal.getLabel())) {
								node.setValue(finiteLiteral);
								replaced[0]++;
							}
							super.meet(node);
						}
					});
			assertThat(replaced[0]).as("exactly one parsed finite constant is replaced").isOne();

			long originalVersion = finiteLiteral.getSemanticVersion();
			assertThat(count(prepared))
					.as("the first evaluation sees the original absent spelling")
					.isEqualTo(5L);

			finiteLiteral.setLabel("ordinary-code");
			assertThat(finiteLiteral.getSemanticVersion()).isGreaterThan(originalVersion);
			assertThat(count(prepared))
					.as("a later evaluation must re-read the current query-owned finite value")
					.isEqualTo(3L);
		}
	}

