	@Test
	void retainedNativeDatasetKeepsItsDictionaryAndAdjacencyProofAcrossInsertion(@TempDir Path root)
			throws Exception {
		try (Fixture fixture = fixture(root);
				SailDataset oldDataset = fixture.store.getBackingStore()
						.getExplicitSailSource()
						.dataset(IsolationLevels.SNAPSHOT)) {
			Literal insertedCode = SimpleValueFactory.getInstance().createLiteral("inserted-after-plan");
			IRI linkedMedication = iri("medication-patient-medication");
			IRI codePredicate = iri("code");
			SailDatasetTripleTermSource oldTripleSource = new SailDatasetTripleTermSource(
					fixture.repository.getValueFactory(), oldDataset);
			NativeLmdbQuerySource oldNative = oldTripleSource.unwrapDataset(NativeLmdbQuerySource.class).orElseThrow();
			assertThat(oldNative.tryRetainDictionaryTermMembership())
					.as("the admitted native dataset can retain its paired dictionary membership")
					.isTrue();
			long oldPredicateId = oldNative.idOf(codePredicate);
			assertThat(oldPredicateId).isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
			assertThat(oldNative.idOf(insertedCode))
					.as("the native pattern compiler cannot resolve the finite object in its retained source")
					.isEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
			assertThat(oldDataset.getStatementCount(linkedMedication, codePredicate, insertedCode)).isZero();

			try (SailRepositoryConnection writer = fixture.repository.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				writer.add(linkedMedication, codePredicate, insertedCode);
				writer.commit();
			}
			assertThat(fixture.store.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS))
					.as(fixture.store.getDirectAdjacencyReadinessDescription())
					.isTrue();

			try (SailDataset newDataset = fixture.store.getBackingStore()
					.getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT)) {
				SailDatasetTripleTermSource newTripleSource = new SailDatasetTripleTermSource(
						fixture.repository.getValueFactory(), newDataset);
				NativeLmdbQuerySource newNative = newTripleSource.unwrapDataset(NativeLmdbQuerySource.class)
						.orElseThrow();
				long newPredicateId = newNative.idOf(codePredicate);
				long newValueId = newNative.idOf(insertedCode);
				assertThat(newPredicateId).isEqualTo(oldPredicateId);
				assertThat(newValueId).isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
				assertThat(oldNative.idOf(insertedCode))
						.as("the retained compiler source keeps its original dictionary membership proof")
						.isEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);
				assertThat(oldDataset.getStatementCount(linkedMedication, codePredicate, insertedCode)).isZero();
				assertThat(newDataset.getStatementCount(linkedMedication, codePredicate, insertedCode)).isEqualTo(1L);
				assertThat(newNative.exactDegree(newPredicateId, newValueId, false)).hasValue(1L);
			}
		}
	}

