	private static Observation observe(SailRepository repository, String sparql, boolean includeInferred) {
		String optimizedPlan;
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery optimizedQuery = prepared(connection, sparql, includeInferred);
			optimizedPlan = optimizedQuery.explain(Explanation.Level.Optimized).toString();
		}
		ByteArrayOutputStream captured = new ByteArrayOutputStream();
		PrintStream previousError = System.err;
		try (PrintStream capture = new PrintStream(captured, true, StandardCharsets.UTF_8);
				SailRepositoryConnection connection = repository.getConnection()) {
			System.setErr(capture);
			SailTupleQuery evaluatedQuery = prepared(connection, sparql, includeInferred);
			QueryResults.asList(evaluatedQuery.evaluate());
			capture.flush();
			List<String> shapes = captured.toString(StandardCharsets.UTF_8)
					.lines()
					.filter(line -> line.startsWith("[ir-aggregate] shape "))
					.map(line -> line.substring("[ir-aggregate] shape ".length()))
					.toList();
			return new Observation(optimizedPlan, shapes.isEmpty() ? "" : shapes.get(shapes.size() - 1));
		} finally {
			System.setErr(previousError);
		}
	}

	private static SailTupleQuery prepared(SailRepositoryConnection connection, String sparql,
			boolean includeInferred) {
		SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(sparql);
		query.setIncludeInferred(includeInferred);
		query.setForcedLmdbExecutionStrategy("irAggregateInterpreted");
		return query;
	}

	private static long count(SailRepository repository, String sparql, boolean includeInferred) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return count(prepared(connection, sparql, includeInferred));
		}
	}

	private static long count(SailTupleQuery query) {
		List<BindingSet> rows = QueryResults.asList(query.evaluate());
		assertThat(rows).as("COUNT DISTINCT returns one aggregate row").hasSize(1);
		return ((Literal) rows.get(0).getValue("count")).longValue();
	}

	private static Fixture fixture(Path root) throws Exception {
		return fixture(root, false);
	}

	private static Fixture fixture(Path root, boolean includeNamedGraph) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc");
		config.setNativeEvaluationEnabled(true);
		config.setExperimentalQueryOptimizations(true);
		config.setSketchEstimatorEnabled(false);
		config.setFrontierEstimatorMode(FrontierEstimatorMode.OFF);
		config.setDirectAdjacencyEnabled(true);
		config.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER);
		config.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.FULL);
		config.setDirectAdjacencyBuildOnStart(false);
		LmdbStore store = new LmdbStore(root.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			addPatient(connection, "patient-medication", "ordinary-code", false);
			addPatient(connection, "patient-encounter", (String) null, true);
			addPatient(connection, "patient-shared", "ordinary-code", true);
			IRI medication = iri("medication-shared-duplicate");
			connection.add(iri("patient-shared"), iri("hasMedication"), medication);
			connection.add(medication, iri("code"), SimpleValueFactory.getInstance().createLiteral("ordinary-code"));
			addPatient(connection, "patient-numeric", SimpleValueFactory.getInstance()
					.createLiteral("003", XSD.INTEGER), false);
			addPatient(connection, "patient-language", SimpleValueFactory.getInstance()
					.createLiteral("Tagged", "EN"), false);
			if (includeNamedGraph) {
				addPatientInGraph(connection, "graph-patient", "graph-code", iri("graph"));
			}

			InferencerConnection inferred = (InferencerConnection) connection.getSailConnection();
			IRI inferredPatient = iri("patient-inferred");
			IRI inferredMedication = iri("medication-inferred");
			inferred.addInferredStatement(inferredPatient, RDF.TYPE, iri("Patient"));
			inferred.addInferredStatement(inferredPatient, iri("name"), SimpleValueFactory.getInstance()
					.createLiteral("patient-inferred"));
			inferred.addInferredStatement(inferredPatient, iri("hasMedication"), inferredMedication);
			inferred.addInferredStatement(inferredMedication, iri("code"), SimpleValueFactory.getInstance()
					.createLiteral("ordinary-code"));
			connection.commit();
		}
		LmdbTestUtil.awaitPostReadyInitialization(store, 30L, TimeUnit.SECONDS);
		if (!AdjacencyEngagementTestAccess.buildNow(store)
				|| !store.awaitDirectAdjacencyReady(30L, TimeUnit.SECONDS)) {
			repository.shutDown();
			throw new AssertionError("FULL direct adjacency did not become ready: "
					+ store.getDirectAdjacencyReadinessDescription());
		}
		return new Fixture(store, repository);
	}

	private static void addPatient(SailRepositoryConnection connection, String localName, String code,
			boolean hasEncounter) {
		ValueFactory values = SimpleValueFactory.getInstance();
		IRI patient = iri(localName);
		connection.add(patient, RDF.TYPE, iri("Patient"));
		connection.add(patient, iri("name"), values.createLiteral(localName));
		if (code != null) {
			IRI medication = iri("medication-" + localName);
			connection.add(patient, iri("hasMedication"), medication);
			connection.add(medication, iri("code"), (org.eclipse.rdf4j.model.Value) values.createLiteral(code));
		}
		if (hasEncounter) {
			IRI encounter = iri("encounter-" + localName);
			connection.add(patient, iri("hasEncounter"), encounter);
			connection.add(encounter, iri("hasObservation"), iri("observation-" + localName));
		}
	}

	private static void addPatient(SailRepositoryConnection connection, String localName, Literal code,
			boolean hasEncounter) {
		ValueFactory values = SimpleValueFactory.getInstance();
		IRI patient = iri(localName);
		IRI medication = iri("medication-" + localName);
		connection.add(patient, RDF.TYPE, iri("Patient"));
		connection.add(patient, iri("name"), values.createLiteral(localName));
		connection.add(patient, iri("hasMedication"), medication);
		connection.add(medication, iri("code"), code);
		if (hasEncounter) {
			IRI encounter = iri("encounter-" + localName);
			connection.add(patient, iri("hasEncounter"), encounter);
			connection.add(encounter, iri("hasObservation"), iri("observation-" + localName));
		}
	}

	private static void addPatientInGraph(SailRepositoryConnection connection, String localName, String code,
			IRI graph) {
		ValueFactory values = SimpleValueFactory.getInstance();
		IRI patient = iri(localName);
		IRI medication = iri("medication-" + localName);
		connection.add(patient, RDF.TYPE, iri("Patient"), graph);
		connection.add(patient, iri("name"), values.createLiteral(localName), graph);
		connection.add(patient, iri("hasMedication"), medication, graph);
		connection.add(medication, iri("code"), values.createLiteral(code), graph);
	}

	private static String countQuery(String witnessCondition) {
		return "PREFIX ex: <" + EX + ">\n"
				+ "SELECT (COUNT(DISTINCT ?patient) AS ?count) WHERE {\n"
				+ outerUnionAndName()
				+ (witnessCondition == null ? ""
						: "  FILTER NOT EXISTS { ?patient ex:hasMedication ?m2 .\n"
								+ "    ?m2 ex:code ?code . " + witnessCondition + " }\n")
				+ "}";
	}

	private static String countQueryWithPositiveExists(String code) {
		return "PREFIX ex: <" + EX + ">\n"
				+ "SELECT (COUNT(DISTINCT ?patient) AS ?count) WHERE {\n"
				+ outerUnionAndName()
				+ "  FILTER EXISTS { ?patient ex:hasMedication ?m2 .\n"
				+ "    VALUES ?code { \"" + code + "\" }\n"
				+ "    ?m2 ex:code ?code . }\n"
				+ "}";
	}

	private static String countQueryInGraph(String graph, String witnessCondition) {
		return "PREFIX ex: <" + EX + ">\n"
				+ "SELECT (COUNT(DISTINCT ?patient) AS ?count) WHERE { GRAPH <" + graph + "> {\n"
				+ outerUnionAndName()
				+ "  FILTER NOT EXISTS { ?patient ex:hasMedication ?m2 .\n"
				+ "    ?m2 ex:code ?code . " + witnessCondition + " }\n"
				+ "} }";
	}

	private static String outerUnionAndName() {
		return "  { { ?patient a ex:Patient ; ex:hasMedication ?med . }\n"
				+ "    UNION\n"
				+ "    { ?patient a ex:Patient ; ex:hasEncounter ?enc . ?enc ex:hasObservation ?obs . } }\n"
				+ "  OPTIONAL { ?patient ex:name ?optName . }\n"
				+ "  FILTER(?optName != \"\")\n";
	}

	private static IRI iri(String localName) {
		return SimpleValueFactory.getInstance().createIRI(EX, localName);
	}

